{
    int place = -1;
    for (int i = 0; i < runners.Length; i++)
    {
        if (runners[i] != null)
        {
            if (runners[i].GetNumber() == r.GetNumber())
            {
                return false;
            }
        }
        else
        {
            if (place == -1)
            {
                place = i;
            }
        }
    }
    if (place == -1)
    {
        return false;
    }
    runners[place] = r;
    return true;
}

