public static void ReverseArray(int[] arr)
{
    int start = 0;
    int end = arr.Length - 1;
    while (start < end)
    {
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

public static bool IsSorted(int[] arr)
{
    for (int i = 0; i < arr.Length - 1; i++)
    {
        if (arr[i] > arr[i + 1])
        {
            return false;
        }
    }
    return true;
}

public static int RemoveConsecutiveDuplicates(int[] arr)
{
    if (arr.Length == 0)
    {
        return 0;
    }
    int newLength = 1;
    for (int i = 1; i < arr.Length; i++)
    {
        if (arr[i] != arr[newLength - 1])
        {
            arr[newLength] = arr[i];
            newLength++;
        }
    }
    return newLength;
}

public static int MaxSubArraySum(int[] arr)
{
    int maxSoFar = arr[0];
    int currentSum = arr[0];
    for (int i = 1; i < arr.Length; i++)
    {
        currentSum = Math.Max(arr[i], currentSum + arr[i]);
        maxSoFar = Math.Max(maxSoFar, currentSum);
    }
    return maxSoFar;
}

public static int EquilibriumIndex(int[] arr)
{
    int totalSum = 0;
    for (int i = 0; i < arr.Length; i++)
        totalSum += arr[i];

    int leftSum = 0;
    for (int i = 0; i < arr.Length; i++)
    {
        int rightSum = totalSum - leftSum - arr[i];
        if (leftSum == rightSum)
        {
            return i;
        }
        leftSum += arr[i];
    }
    return -1;
}

public static void RotateLeft(int[] arr, int k)
{
    int n = arr.Length;
    k = k % n;

    Reverse(arr, 0, k - 1);
    Reverse(arr, k, n - 1);
    Reverse(arr, 0, n - 1);
}

private static void Reverse(int[] arr, int start, int end)
{
    while (start < end)
    {
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

public static bool HasPairWithSum(int[] arr, int target)
{
    int[] sorted = (int[])arr.Clone();
    Array.Sort(sorted);

    int left = 0;
    int right = sorted.Length - 1;

    while (left < right)
    {
        int currentSum = sorted[left] + sorted[right];
        if (currentSum == target)
        {
            return true;
        }
        else if (currentSum < target)
        {
            left++;
        }
        else
        {
            right--;
        }
    }
    return false;
}

public static int[] FindMissingAndDuplicate(int[] arr)
{
    int n = arr.Length;
    long expectedSum = (long)n * (n + 1) / 2;
    long expectedSumSquares = (long)n * (n + 1) * (2 * n + 1) / 6;

    long actualSum = 0;
    long actualSumSquares = 0;

    for (int i = 0; i < n; i++)
    {
        actualSum += arr[i];
        actualSumSquares += (long)arr[i] * arr[i];
    }

    long sumDiff = actualSum - expectedSum;
    long squareDiff = actualSumSquares - expectedSumSquares;

    long sumTotal = squareDiff / sumDiff;
    long duplicate = (sumDiff + sumTotal) / 2;
    long missing = sumTotal - duplicate;

    return new int[] { (int)duplicate, (int)missing };
}
